package com.gerenciadorrural.modules.herd.api;
import com.fasterxml.jackson.databind.*; import com.gerenciadorrural.infrastructure.database.*; import com.nimbusds.jose.*; import com.nimbusds.jose.crypto.MACSigner; import com.nimbusds.jwt.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.*; import org.springframework.test.context.ActiveProfiles; import org.springframework.test.web.servlet.*; import org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder; import java.sql.*; import java.time.*; import java.util.*; import static org.assertj.core.api.Assertions.assertThat; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
@ActiveProfiles("test") @SpringBootTest(properties={"app.security.supabase.mode=HMAC","app.security.supabase.algorithm=HS256","app.security.supabase.issuer=https://auth.example.test/auth/v1","app.security.supabase.hmac-secret=test-only-hmac-key-with-at-least-32-bytes","app.security.supabase.audiences=authenticated","app.security.supabase.accepted-token-roles=authenticated"}) @AutoConfigureMockMvc class HerdCrossFarmTransferVerticalIntegrationTest extends SpringPostgresTestSupport {private static final String ISSUER="https://auth.example.test/auth/v1",SECRET="test-only-hmac-key-with-at-least-32-bytes";@Autowired MockMvc mvc;@Autowired ObjectMapper json;UUID user,tenant,source,destination,membership;String token;@BeforeEach void seed()throws Exception{PostgresTestEnvironment.clearUsers();user=UUID.randomUUID();tenant=UUID.randomUUID();source=UUID.randomUUID();destination=UUID.randomUUID();membership=UUID.randomUUID();try(Connection c=PostgresTestEnvironment.adminConnection();PreparedStatement s=c.prepareStatement("insert into app.users(id,status) values(?,'ACTIVE');insert into app.organizations(id,name,status) values(?,'T','ACTIVE');insert into app.farms(id,tenant_id,name,status) values(?,?,'Origem','ACTIVE'),(?,?, 'Destino','ACTIVE');insert into app.organization_memberships(id,tenant_id,user_id,role_key,status,farm_scope_mode) values(?,?,?,'OWNER','ACTIVE','SELECTED_FARMS');insert into app.membership_farm_scopes(tenant_id,membership_id,farm_id) values(?,?,?),(?,?,?)")){s.setObject(1,user);s.setObject(2,tenant);s.setObject(3,source);s.setObject(4,tenant);s.setObject(5,destination);s.setObject(6,tenant);s.setObject(7,membership);s.setObject(8,tenant);s.setObject(9,user);s.setObject(10,tenant);s.setObject(11,membership);s.setObject(12,source);s.setObject(13,tenant);s.setObject(14,membership);s.setObject(15,destination);s.executeUpdate();}token=token(user);}@Test void transfersIdentityReplaysAndScopesHistory()throws Exception{UUID animal=UUID.randomUUID(),paddock=UUID.randomUUID(),op=UUID.randomUUID();status(post("/api/v1/herd/animals"),"{\"id\":\""+animal+"\",\"identification\":\"BR-1\",\"sex\":\"FEMALE\"}",201);status(post("/api/v1/herd/paddocks"),"{\"id\":\""+paddock+"\",\"name\":\"Destino\"}",201,destination);String body="{\"operationId\":\""+op+"\",\"expectedVersion\":0,\"destinationFarmId\":\""+destination+"\",\"destinationPaddockId\":\""+paddock+"\",\"occurredOn\":\"2026-09-09\"}";status(post("/api/v1/herd/animals/"+animal+"/transfers"),body,200);status(post("/api/v1/herd/animals/"+animal+"/transfers"),body,200);status(get("/api/v1/herd/animals/"+animal),null,404);JsonNode profile=json.readTree(request(get("/api/v1/herd/animals/"+animal),null,destination).getResponse().getContentAsString());assertThat(profile.path("paddock").path("id").asText()).isEqualTo(paddock.toString());assertThat(json.readTree(request(get("/api/v1/herd/transfers?direction=OUT"),null,source).getResponse().getContentAsString()).path("totalElements").asInt()).isOne();assertThat(json.readTree(request(get("/api/v1/herd/transfers?direction=IN"),null,destination).getResponse().getContentAsString()).path("totalElements").asInt()).isOne();try(Connection c=PostgresTestEnvironment.adminConnection();PreparedStatement s=c.prepareStatement("select count(*) from app.animal_transfers where animal_id=?")){s.setObject(1,animal);ResultSet r=s.executeQuery();r.next();assertThat(r.getInt(1)).isOne();}}private MvcResult request(MockHttpServletRequestBuilder r,String content,UUID farm)throws Exception{r.header(HttpHeaders.AUTHORIZATION,"Bearer "+token).header("X-Organization-Id",tenant).header("X-Farm-Id",farm);if(content!=null)r.contentType(MediaType.APPLICATION_JSON).content(content);return mvc.perform(r).andReturn();}private void status(MockHttpServletRequestBuilder r,String content,int expected)throws Exception{status(r,content,expected,source);}private void status(MockHttpServletRequestBuilder r,String content,int expected,UUID farm)throws Exception{assertThat(request(r,content,farm).getResponse().getStatus()).isEqualTo(expected);}private static String token(UUID id)throws Exception{JWTClaimsSet c=new JWTClaimsSet.Builder().issuer(ISSUER).audience("authenticated").subject(id.toString()).claim("role","authenticated").issueTime(new java.util.Date()).expirationTime(java.util.Date.from(Instant.now().plusSeconds(300))).build();SignedJWT jwt=new SignedJWT(new JWSHeader(JWSAlgorithm.HS256),c);jwt.sign(new MACSigner(SECRET.getBytes()));return jwt.serialize();}}
